class Vector:
    def __init__(self, x, y, z):
        self.x, self.y, self.z = x, y, z

    def __add__(self, other):
        return Vector(self.x + other.x,
                      self.y + other.y,
                      self.z + other.z)

    def __repr__(self):
        return f'Vector({self.x}, {self.y}, {self.z})'

print(Vector(1, 2, 3) + Vector(4, 5, 6))

